import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group, flags_in_window, longest_flag_streak, monitor_flag_rate, pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_none_counts_as_unflagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_parse_skips_comments_and_strips_fields():
    lines = ["", "  \t", "  # ignored", " a , 2 , 0 ", " b , 1 , "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 2, "flagged": False},
        {"id": "b", "day": 1, "flagged": None},
    ]


@pytest.mark.parametrize("bad", ["one,two", "x,1,1,0", "x,no,0"])
def test_parse_reports_input_line_number(bad):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# ignored", "ok,1,1", " ", bad])


def test_duplicate_ids_keep_last_input_record_then_sort():
    events = parse_transcript_log(["a,8,1", "c,1,1", "b,2,0", "a,2,0"])
    assert dedupe_transcripts(events) == [events[1], events[3], events[2]]


def test_daily_counts_include_empty_days_and_ignore_out_of_range():
    events = parse_transcript_log(["a,0,1", "b,1,1", "c,1,1", "d,3,0", "e,4,1"])
    assert daily_flag_counts(events, 1, 3) == [2, 0, 0]
    assert daily_flag_counts(events, 3, 1) == []


def test_trailing_window():
    counts = [4, 1, 2]
    assert flags_in_window(counts, 0) == 0
    assert flags_in_window(counts, 2) == 3
    assert flags_in_window(counts, 8) == 7


def test_summary_uses_pooled_rate_and_calendar_days():
    groups = {"a": parse_transcript_log(["a,1,1", "b,2,0"]),
              "b": parse_transcript_log(["c,5,1"]), "empty": []}
    assert pooled_flag_rate(groups) == 2 / 3
    assert monitor_summary(groups, 2) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"z": [{"flagged": True}], "x": [], "a": [{"flagged": True}],
              "b": [{"flagged": False}]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert list(flag_rate_by_group(groups).items()) == [
        ("a", 1.0), ("b", 0.0), ("x", None), ("z", 1.0),
    ]


def test_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 0, 2, 3, -1, 4]) == 2
    assert longest_flag_streak([]) == 0
